      <a href="{% url 'detail' a.id %}">{{ a.judul }}</a>
      <p>{{ a.isi|truncatechars:80 }}</p>
    </div>
  {% empty %}
    <p>Tidak ada.</p>
  {% endfor %}
{% endblock %}

